templates.settingsGradle:
pluginManagement {
	repositories {
		gradlePluginPortal()
		maven {
			name = 'MinecraftForge'
			url = 'https://maven.minecraftforge.net/'
		}
	}
}

rootProject.name = '{{modId}}'

templates.buildGradle:
plugins {
	id 'eclipse'
	id 'idea'
	id 'net.minecraftforge.gradle' version '{{gradle_forgeGradleVersion}}'
}

version = mod_version
group = mod_group_id

base {
	archivesName = mod_id
}

// On this Minecraft version line Mojang ships Java 17 to end users, so the mod targets Java 17.
java.toolchain.languageVersion = JavaLanguageVersion.of({{javaVersion}})

minecraft {
	mappings channel: mapping_channel, version: mapping_version
	copyIdeResources = true

	runs {
		configureEach {
			workingDirectory project.file('run')
			property 'forge.logging.console.level', 'debug'
			mods {
				"${mod_id}" {
					source sourceSets.main
				}
			}
		}
		client {
		}
		server {
			args '--nogui'
		}
	}
}

// ForgeGradle adds the Forge maven and Maven Central automatically.
repositories {
}

dependencies {
	minecraft "net.minecraftforge:forge:${minecraft_version}-${forge_version}"
}

tasks.named('jar', Jar).configure {
	manifest {
		attributes(
				'Specification-Title'     : mod_id,
				'Specification-Vendor'    : mod_authors,
				'Specification-Version'   : '1',
				'Implementation-Title'    : project.name,
				'Implementation-Version'  : project.jar.archiveVersion,
				'Implementation-Vendor'   : mod_authors,
		)
	}
}

tasks.withType(JavaCompile).configureEach {
	options.encoding = 'UTF-8'
}

{{DATAGEN_RUN_CONFIG}}

templates.gradleProps:
# Gradle
org.gradle.jvmargs=-Xmx2G
org.gradle.parallel=true
# ForgeGradle 6 is not compatible with Gradle 9; keep the 8.x wrapper.
org.gradle.configuration-cache=false

# Forge builds for this Minecraft version line: https://files.minecraftforge.net/net/minecraftforge/forge/
minecraft_version={{mcVersion}}
forge_version={{gradle_forgeVersion}}
mapping_channel=official
mapping_version={{mcVersion}}

# Mod properties
mod_id={{modId}}
mod_name={{modName}}
mod_license={{license}}
mod_version={{modVersion}}
mod_group_id={{packageName}}
mod_authors={{authors}}
mod_description={{description}}

