package {{packageName}};

import com.mojang.logging.LogUtils;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.eventbus.api.IEventBus;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.javafmlmod.FMLJavaModLoadingContext;
import org.slf4j.Logger;

/** Entry point of {{modName}} (generated by mcmodkit). */
@Mod({{mainClassSimpleName}}.MOD_ID)
public class {{mainClassSimpleName}} {

	public static final String MOD_ID = "{{modId}}";
	public static final Logger LOGGER = LogUtils.getLogger();

	public {{mainClassSimpleName}}(FMLJavaModLoadingContext context) {
		IEventBus modEventBus = context.getModEventBus();
		{{mainClassSimpleName}}Items.register(modEventBus);
		{{mainClassSimpleName}}Blocks.register(modEventBus);
{{REGISTRY_INIT_CALLS}}
		LOGGER.info("{} loaded", MOD_ID);
	}

	public static ResourceLocation id(String path) {
		return ResourceLocation.fromNamespaceAndPath(MOD_ID, path);
	}
}

